export function cargarFilmoteca(base = './filmoteca/', { paquetes = 8 } = {}) {
  const cache = new Map();
  const paquete = (nombre) => {
    let p = cache.get(nombre);
    if (p) { cache.delete(nombre); cache.set(nombre, p); return p; }
    p = fetch(base + nombre).then(r => { if (!r.ok) throw new Error(r.status + ' ' + nombre); return r.arrayBuffer(); });
    p.catch(() => cache.delete(nombre));
    cache.set(nombre, p);
    while (cache.size > paquetes) cache.delete(cache.keys().next().value);
    return p;
  };
  const pieza = (prefijo, [n, off, len]) => () => paquete(`${prefijo}-${String(n).padStart(2, '0')}.bin`)
    .then(buf => createImageBitmap(new Blob([new Uint8Array(buf, off, len)], { type: 'image/webp' })));
  return FILMOTECA.map(f => ({ ...f, poster: f.p ? pieza('posters', f.p) : undefined, backdrop: f.b ? pieza('fotogramas', f.b) : undefined }));
}
